/* ---------- Run queue ---------- */
/* a queue of agent jobs in three parts, on one left edge: the job running, raised, with its agent, its steps, a progress
   bar and the time left; the jobs up next, each with its agent and when it should start; and the jobs done, each with how
   long it took and a green tick. A job glides from one part to the next as it moves, a part with nothing in it folds away,
   and when every job is done a summary takes the running job's place */
.rq{display:flex;flex-direction:column;padding:var(--dm-s-3);text-align:left}
.rq-h{display:flex;align-items:center;justify-content:space-between;gap:var(--dm-s-3)}
.rq-ht{display:flex;flex-direction:column;min-width:0}
.rq-ht b{font-weight:500}
.rq-st{font-size:12.5px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
/* the whole queue at a glance: a part of the strip for each job, filled as it runs */
.rq-tot{display:flex;gap:3px;margin-top:var(--dm-s-3)}
.rq-tot i{flex:1;height:4px;border-radius:2px;background:var(--dm-line);overflow:hidden}
.rq-tot b{display:block;height:100%;border-radius:inherit;background:var(--dm-accent-mark,var(--dm-accent));transform-origin:left;transform:scaleX(var(--dm-p,0));transition:transform .3s linear,background .3s}
.rq-tot i.fail b{background:var(--dm-bad)}
/* the end of the queue keeps the room it had and centres what is left in it */
.rq-b{flex:1;display:flex;flex-direction:column}
.rq.fin .rq-b{justify-content:center}
.rq-sec{display:flex;flex-direction:column;gap:6px;padding-top:var(--dm-s-3)}
.rq-l{display:flex;align-items:baseline;gap:6px;font-size:12px;color:var(--dm-muted)}
.rq-l .num{color:var(--dm-fg2)}
.rq-none{display:none;align-items:center;min-height:40px;margin:0;font-size:12.5px;color:var(--dm-muted)}
.rq-next:empty+.rq-none,.rq-done:empty+.rq-none{display:flex}
.rq-run,.rq-next,.rq-done{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:2px}
/* a job: its agent's badge, what it is and who does it, and its time */
.rq-j{display:flex;flex-direction:column;border-radius:var(--dm-r-in);font-size:13px}
.rq-jh{display:flex;align-items:center;gap:10px;min-height:40px}
.rq-av{position:relative;width:28px;height:28px;border-radius:calc(9px * var(--dm-rk));display:grid;place-items:center;flex:none;background:var(--dm-chip);color:var(--dm-fg2);transition:background .3s,color .3s}
.rq-av .i{width:13px;height:13px;stroke-width:1.9}
.rq-jt{flex:1;min-width:0;display:flex;flex-direction:column}
.rq-jt b{font-weight:400;color:var(--dm-fg2);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;transition:color .3s}
.rq-js{font-size:12px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.rq-jm{display:flex;align-items:center;gap:6px;flex:none;font-size:12px;color:var(--dm-muted);white-space:nowrap}
.rq-jm .ok{display:grid;color:var(--dm-ok)}
.rq-jb{display:none;align-items:center;gap:10px;padding:0 0 2px 38px}
.rq-bar{flex:1;height:4px;border-radius:2px;background:var(--dm-line);overflow:hidden}
.rq-bar i{display:block;height:100%;border-radius:inherit;background:var(--dm-accent-mark,var(--dm-accent));transform-origin:left;transform:scaleX(var(--dm-p,0));transition:transform .2s linear}
.rq-pc{width:32px;flex:none;font-size:12px;color:var(--dm-muted);text-align:right}
/* the job running: raised on the surface, its badge in the accent, with its progress and its steps */
.rq-j:is([data-s="run"],[data-s="fail"]){padding:var(--dm-s-1) 10px 10px;background:var(--dm-surface);box-shadow:var(--dm-shadow);gap:6px}
.rq-j:is([data-s="run"],[data-s="fail"]) .rq-jb{display:flex}
.rq-j:is([data-s="run"],[data-s="fail"]) .rq-jt b{font-weight:500;color:var(--dm-fg)}
.rq-j[data-s="run"] .rq-av{background:var(--dm-accent-bg);color:var(--dm-accent-fg,var(--dm-accent))}
.rq-j[data-s="done"] .rq-jt b{color:var(--dm-fg2)}
/* a failed step turns the job red until Retry */
.rq-j[data-s="fail"]{background:var(--dm-bad-bg);box-shadow:none}
.rq-j[data-s="fail"] .rq-av{background:var(--dm-surface);color:var(--dm-bad)}
.rq-j[data-s="fail"] :is(.rq-jt b,.rq-jm,.rq-pc){color:var(--dm-bad)}
.rq-j[data-s="fail"] .rq-js{color:var(--dm-fg2)}
.rq-j[data-s="fail"] .rq-bar{background:color-mix(in srgb,var(--dm-bad) 18%,transparent)}
.rq-j[data-s="fail"] .rq-bar i{background:var(--dm-bad)}
.rq-steps{list-style:none;margin:0;padding:var(--dm-s-1) 0 0 38px;display:flex;flex-direction:column}
.rq-sp{display:flex;align-items:center;gap:var(--dm-s-2);min-height:26px;font-size:12.5px;color:var(--dm-fg2)}
.rq-sp .g{width:14px;display:grid;place-items:center;flex:none}
.rq-sp .g .spin{width:10px;height:10px}
.rq-sp .g .dot{width:5px;height:5px;color:var(--dm-faint)}
.rq-sp .m{margin-left:auto;font-size:12px;color:var(--dm-muted)}
.rq-sp.wait{color:var(--dm-muted)}
.rq-sp.done .g{color:var(--dm-ok)}
.rq-sp.fail,.rq-sp.fail .g{color:var(--dm-bad)}
.rq-retry{height:24px;padding:0 10px;border-radius:var(--dm-r-pill);background:var(--dm-surface);box-shadow:var(--dm-shadow);font-size:12px;font-weight:500;color:var(--dm-fg);transition:box-shadow .2s,transform .15s}
.rq-retry.on{box-shadow:var(--dm-shadow-pop)}
@media (hover:hover) and (pointer:fine){.rq-retry:hover{box-shadow:var(--dm-shadow-pop)}}
.rq-retry:active{transform:scale(.96)}
/* the end: every job done, said once in green where the running job was */
.rq-fin{display:flex;align-items:center;gap:10px;padding:10px;border-radius:var(--dm-r-in);background:var(--dm-ok-bg)}
.rq-fin .rq-av{background:var(--dm-surface);color:var(--dm-ok)}
.rq-fin b{font-weight:500;color:var(--dm-ok)}
.rq-fin .rq-js{color:var(--dm-fg2)}
.rq-say{position:absolute;width:1px;height:1px;margin:-1px;padding:0;border:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
@container (max-width:340px){.rq-h{flex-wrap:wrap}.rq-jb,.rq-steps{padding-left:0}}
:root:not([data-style="soft"]) .rq-j:is([data-s="run"],[data-s="fail"]):not(:where([data-style="soft"],[data-style="soft"] *)){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 70%,transparent)}
:root:not([data-style="soft"]) .rq-j[data-s="run"]:not(:where([data-style="soft"],[data-style="soft"] *)){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-accent-mark,var(--dm-accent)) 45%,transparent)}
:root:not([data-style="soft"]) .rq-j[data-s="fail"]:not(:where([data-style="soft"],[data-style="soft"] *)){background:repeating-linear-gradient(135deg,transparent 0 5px,color-mix(in srgb,var(--dm-bad) 10%,transparent) 5px 6px),var(--dm-bad-bg);box-shadow:none}
:root:not([data-style="soft"]) .rq-bar i:not(:where([data-style="soft"],[data-style="soft"] *)),:root:not([data-style="soft"]) .rq-tot b:not(:where([data-style="soft"],[data-style="soft"] *)){transition:transform .2s steps(2,end)}
:root:not([data-style="soft"]) .rq-retry:not(:where([data-style="soft"],[data-style="soft"] *)){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 70%,transparent)}

DM.def('run-queue', (r, c) => {
  // the jobs, run one at a time: what each is, the agent on it and its icon, and its steps with what each came to. The launch
  // email's test send fails once and waits for Retry
  const J = [
    { t:'Research three competitors', ag:'Research agent', ic:'search', subs:[['Read their pricing pages', '3 of 3'], ['Compared plans and limits', '5 gaps']] },
    { t:'Draft the launch email', ag:'Copy agent', ic:'mail', fail:2, subs:[['Pulled the new features', '6 items'], ['Wrote two subject lines', '2 drafts'], ['Sent a test to the team', 'Sent']] },
    { t:'Update the help centre', ag:'Docs agent', ic:'book', subs:[['Billing questions', '4 articles'], ['Inviting your team', '2 articles']] },
    { t:'Post the changelog', ag:'Release agent', ic:'send', subs:[['Posted in #releases', 'Posted']] }
  ];
  const STEP = 1.4, secs = j => j.subs.length * STEP;
  const root = $('.rq', r), st = $('.rq-st', r), tot = $('.rq-tot', r), say = $('.rq-say', r);
  const runL = $('.rq-run', r), nextL = $('.rq-next', r), doneL = $('.rq-done', r), dn = $('.rq-dn', r);
  $('.rq-fin .rq-av', r).innerHTML = I('ok');
  const fold = (f, on) => { f.classList.toggle('shut', !on); f.inert = !on; };
  $$('.rq-b>.fold', r).forEach(f => { f.inert = f.classList.contains('shut'); });
  let compact = false, total = 0, retries = 0;
  tot.innerHTML = J.map(() => '<i><b></b></i>').join('');
  J.forEach((j, k) => {
    j.bar = $$('b', tot)[k]; j.p = 0; j.s = '';
    j.el = html(`<li class="rq-j" data-s="wait"><div class="rq-jh"><span class="rq-av" aria-hidden="true">${I(j.ic)}</span><span class="rq-jt"><b>${j.t}</b><span class="rq-js">${j.ag}</span></span><span class="rq-jm num"></span></div><div class="rq-jb" aria-hidden="true"><div class="rq-bar"><i></i></div><span class="rq-pc num">0%</span></div><div class="fold shut rq-sf"><div><ul class="rq-steps">${j.subs.map(s => `<li class="rq-sp wait"><span class="g"><span class="dot"></span></span><span>${s[0]}</span><span class="m"></span></li>`).join('')}</ul></div></div></li>`);
    $('.rq-sf', j.el).inert = true;
    nextL.appendChild(j.el);
  });
  const text = (el, t) => { if (el.textContent !== t) el.textContent = t; };
  // when each waiting job should start: after what is left of the one running and of every job ahead of it
  const left = j => secs(j) * (1 - j.p);
  function times(){
    let ahead = 0;
    J.forEach(j => {
      const m = $('.rq-jm', j.el);
      if (j.s === 'run' || j.s === 'fail'){ ahead += left(j); if (j.s === 'run') text(m, left(j) < .5 ? 'Finishing' : `${Math.ceil(left(j))}s left`); }
      else if (!j.s){ text(m, `in ~${Math.max(1, Math.round(ahead))}s`); ahead += secs(j); }
    });
    const now = J.find(j => j.s === 'run' || j.s === 'fail'), d = J.filter(j => j.s === 'done').length;
    text(st, d === J.length ? `All ${J.length} done in ${total.toFixed(1)}s` : now && now.s === 'fail' ? '1 step failed, waiting for Retry' : `${d} of ${J.length} done · ~${Math.ceil(ahead)}s left`);
  }
  // a job moves to its part of the queue, and every job glides from where it was to where it is now
  function move(j, list, s){
    const was = new Map(J.map(x => [x, x.el.getBoundingClientRect()]));
    j.s = s; j.el.dataset.s = s || 'wait'; list.appendChild(j.el); steps(j);
    if (REDUCE) return;
    J.forEach(x => { const a = was.get(x), b = x.el.getBoundingClientRect(), dx = a.left - b.left, dy = a.top - b.top;
      if (Math.abs(dx) + Math.abs(dy) > 1) x.el.animate([{ transform:`translate(${dx}px,${dy}px)` }, { transform:'none' }], { duration:520, easing:'cubic-bezier(.22,1,.36,1)' }); });
  }
  // the queue keeps the tallest room it has needed once each move settles, so it never shrinks while it runs and its end
  // sits centred in that room
  const keep = () => { const h = Math.ceil(root.getBoundingClientRect().height); if (h > (parseFloat(root.style.minHeight) || 0)) root.style.minHeight = h + 'px'; };
  function steps(j){ const f = $('.rq-sf', j.el); fold(f, !compact && (j.s === 'run' || j.s === 'fail')); }
  seg($('.seg2', r), v => { compact = v === 'compact'; J.forEach(steps); });
  const paint = j => { j.bar.style.setProperty('--dm-p', j.p.toFixed(3)); $('.rq-bar i', j.el).style.setProperty('--dm-p', j.p.toFixed(3)); text($('.rq-pc', j.el), Math.round(j.p * 100) + '%'); };
  const glyph = (sp, g, cls) => { sp.className = 'rq-sp ' + cls; $('.g', sp).innerHTML = g; };
  async function go(j){
    if (j.s !== 'run') move(j, runL, 'run');
    say.textContent = `${j.t} started`; c.later(600, keep);
    const sps = $$('.rq-sp', j.el), js = $('.rq-js', j.el), n = j.subs.length;
    let took = 0;
    for (let i = 0; i < n; i++){
      const sp = sps[i]; glyph(sp, '<span class="spin"></span>', 'run'); swap(js, `${j.ag} · ${j.subs[i][0]}`);
      // the step fills its share of the bar a tenth of a second at a time; the test send fails part way, once
      let q = 0; const failAt = j.fail === i && !j.failed ? .55 : 2;
      await new Promise(res => { const iv = c.every(100, () => { q = Math.min(1, q + .1 / STEP); took += .1; j.p = (i + q) / n; paint(j); times(); if (q >= failAt || q >= 1){ clearInterval(iv); res(); } }); });
      if (q < 1){
        j.failed = true; j.el.dataset.s = j.s = 'fail'; j.bar.parentElement.classList.add('fail'); glyph(sp, I('x','xs'), 'fail');
        text($('.rq-jm', j.el), 'Test send failed'); times(); say.textContent = `${j.t}: ${j.subs[i][0]} failed`;
        const b = html('<button class="rq-retry" type="button">Retry</button>'); $('.m', sp).appendChild(b); enter(b);
        // it waits for Retry, which presses itself after a moment so the run never stalls, until the visitor takes over
        await new Promise(res => { b.onclick = res; c.auto(2600, () => { if (b.isConnected){ b.classList.add('on'); c.auto(220, res); } }); });
        b.remove(); retries++; j.el.dataset.s = j.s = 'run'; j.bar.parentElement.classList.remove('fail'); i--; continue;
      }
      glyph(sp, I('check','xs'), 'done'); swap($('.m', sp), j.subs[i][1]);
    }
    total += took; j.p = 1; paint(j); swap(js, j.ag);
    await c.wait(REDUCE ? 0 : 420);
    move(j, doneL, 'done'); dn.textContent = doneL.children.length;
    $('.rq-jm', j.el).innerHTML = `<span>${took.toFixed(1)}s${j.failed ? ' · 1 retry' : ''}</span><span class="ok">${I('check','xs')}</span>`;
    say.textContent = `${j.t} done`; times();
  }
  // the first job is on its way from the start
  move(J[0], runL, 'run'); times();
  c.run(async () => {
    await c.wait(700);
    for (const j of J) await go(j);
    // the end: a summary takes the running job's place, the empty parts fold away, and what is left sits centred in the
    // room the queue kept
    await c.wait(REDUCE ? 0 : 560); keep();
    text($('.rq-ft', r), `All ${J.length} jobs done`); $('.rq-fs', r).textContent = `${total.toFixed(1)}s in all · ${retries ? retries + (retries > 1 ? ' retries' : ' retry') : 'no retries'}`;
    root.classList.add('fin'); fold($('.rq-ff', r), true); fold($('.rq-rf', r), false); fold($('.rq-nf', r), false);
    times(); say.textContent = `All ${J.length} jobs done`;
  });
});
